from collections import deque

def resolve(path, cwd, links):
    def split(p):
        return [c for c in p.split('/') if c not in ('', '.')]

    if not path.startswith('/'):
        # combine cwd and path
        initial = split(cwd) + split(path)
    else:
        initial = split(path)

    queue = deque(initial)
    resolved = []  # list of path segments representing current resolved path
    link_count = 0

    while queue:
        comp = queue.popleft()
        if comp == '..':
            if resolved:
                resolved.pop()
            continue
        # append comp and check for link
        resolved.append(comp)
        candidate = '/' + '/'.join(resolved)
        if candidate in links:
            link_count += 1
            if link_count > 8:
                return None
            target = links[candidate]
            # remove the component we just added, since it's replaced by link resolution
            resolved.pop()
            if target.startswith('/'):
                new_components = split(target)
                resolved = []
                queue = deque(new_components) + queue
            else:
                # relative to directory containing the link, which is current resolved (after pop)
                new_components = split(target)
                queue = deque(new_components) + queue
        # else just continue, comp stays in resolved

    if not resolved:
        return '/'
    return '/' + '/'.join(resolved)

